const categoryCounts = new Map(projectCategories.map(({ slug }) => [slug, 0]));

for (const playbook of projectPlaybooks) {
  if (!categoryCounts.has(playbook.category)) throw new Error(`Unknown project category: ${playbook.category}`);
  categoryCounts.set(playbook.category, categoryCounts.get(playbook.category) + 1);
  if (playbook.links.length < 4) throw new Error(`${playbook.slug} needs at least four links`);
  if (playbook.links.some((row) => !Array.isArray(row) || row.length !== 4 || row.some((value) => typeof value !== "string" || !value.trim()))) throw new Error(`${playbook.slug} links need href, label, kind, and description`);
  if (playbook.briefFields.length !== 4) throw new Error(`${playbook.slug} needs four brief fields`);
  if (playbook.materials.length < 4) throw new Error(`${playbook.slug} needs at least four materials`);
  if (playbook.decisions.length !== 3) throw new Error(`${playbook.slug} needs three decisions`);
  if (playbook.phases.map(({ name }) => name).join("|") !== "Measure|Plan|Cut|Assemble|Install|Closeout") throw new Error(`${playbook.slug} has invalid phases`);
  if (playbook.phases.some(({ tasks }) => tasks.length !== 3)) throw new Error(`${playbook.slug} needs three tasks per phase`);
  if (playbook.variations.length !== 3 || playbook.variations.some((item) => !item || typeof item !== "object" || [item.title, item.condition, item.impact].some((value) => typeof value !== "string" || !value.trim()))) throw new Error(`${playbook.slug} needs three structured variations`);
  if (playbook.risks.length !== 4 || playbook.risks.some((item) => !item || typeof item !== "object" || [item.title, item.signal, item.response].some((value) => typeof value !== "string" || !value.trim()))) throw new Error(`${playbook.slug} needs four structured risks`);
  if (!playbook.finishLine || typeof playbook.finishLine !== "object" || typeof playbook.finishLine.summary !== "string" || !playbook.finishLine.summary.trim() || !Array.isArray(playbook.finishLine.checks) || playbook.finishLine.checks.length < 3 || playbook.finishLine.checks.some((item) => typeof item !== "string" || !item.trim())) throw new Error(`${playbook.slug} needs a structured finish line with observable checks`);
  for (const item of playbook.decisions) {
    if (item.options.length !== 3) throw new Error(`${playbook.slug} decisions need three options`);
    if (item.options.map(({ points }) => points).join("|") !== "3|1|0") throw new Error(`${playbook.slug} decision points must be 3, 1, 0`);
    if (item.options.map(({ status }) => status).join("|") !== "strong|conditional|stop") throw new Error(`${playbook.slug} decision statuses are invalid`);
  }
}

if (projectPlaybooks.length !== 18) throw new Error(`Expected 18 project playbooks, received ${projectPlaybooks.length}`);
for (const [category, count] of categoryCounts) {
  if (count !== 3) throw new Error(`Expected three playbooks in ${category}, received ${count}`);
}
